import React, { useEffect, useRef, useState } from 'react';
import { Link, router, useForm } from '@inertiajs/react';
import { ArrowDown, ArrowRight, ArrowUpRight, Award, BookOpen, Check, CheckCircle2, ChevronRight, Clock3, Code2, Database, Flame, FolderCode, Globe2, GraduationCap, KeyRound, Layers, Leaf, LockKeyhole, Mail, Play, Plus, Search, ShieldCheck, ShoppingBag, Sparkles, Terminal, TrendingUp, Trophy, Users, WandSparkles } from 'lucide-react';
