export const money = (value: any) => Number(value || 0) === 0 ? 'Gratis' : new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(value));
const rows = (value:any): any[] => Array.isArray(value) ? value : value?.data || [];
const dates = (value:any) => value ? new Date(value).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}) : '—';
function requestKey(){if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`;}
const icons = [Code2, Database, ShieldCheck, Globe2, TrendingUp];
const colors = ['mint','lavender','butter','blue','peach'];

export function CourseCard({ course, index = 0 }: any) {
  const color = course.color || colors[index % colors.length];
  return <Link href={`/belajar/course/${course.slug}`} className="course-card"><div className={`course-cover ${color}`} style={String(color).startsWith('#') ? {backgroundColor:color}:undefined}><div className="course-cover-grid"/><span className="course-cover-label">TERAS NGULIK / CLASSROOM</span><span className="cover-code">{index % 3 === 0 ? '< / >' : index % 3 === 1 ? '{ data }' : '( ideas )'}</span><span className="cover-orbit one"/><span className="cover-orbit two"/><span className="course-type"><Code2 size={13}/> BELAJAR + PRAKTIK</span></div><div className="course-card-body"><div className="course-card-top"><span className="course-category">{course.academy?.name || course.academy_name || 'Programming'}</span><span className="tiny-dot"/> <span className="muted">{course.level || 'Pemula'}</span></div><h3>{course.title}</h3><p>{course.summary || course.description}</p><div className="course-card-meta"><span><BookOpen size={14}/>{course.lessons_count || course.lesson_count || 'Materi'} {course.lessons_count || course.lesson_count ? 'materi' : 'interaktif'}</span>{course.duration_minutes && <span><Clock3 size={14}/>{course.duration_minutes} menit</span>}</div><div className="course-card-footer"><strong className={(!course.price || course.access === 'free') ? 'free-price':''}>{course.access === 'subscription' ? 'Langganan' : money(course.price)}</strong><span className="round-arrow"><ArrowUpRight size={18}/></span></div></div></Link>;
}

