    <section className="section courses-section"><div className="container"><div className="section-heading"><div><p className="eyebrow"><span/> {english ? 'YOUR FIRST SMALL STEP':'SATU LANGKAH KECIL DULU'}</p><h2>{english ? 'Less scrolling. More learning.':'Dari “pengen bisa” jadi bisa.'}</h2></div><Link href="/belajar/course" className="text-link">{english ? 'Explore all courses':'Lihat semua course'} <ArrowRight size={17}/></Link></div>{courses.length ? <div className="grid grid-3">{courses.slice(0,3).map((course:any,i:number) => <CourseCard course={course} index={i} key={course.id}/>)}</div> : <div className="empty-state"><BookOpen size={32}/><h3>Kelas baru sedang disiapkan.</h3><p>Sambil menunggu, coba buat sesuatu di playground.</p><Link href="/labs/playground" className="btn btn-primary">Buka playground <ArrowRight size={16}/></Link></div>}<p className="demo-label">Materi contoh untuk eksplorasi platform. Temukan label dan jenis akses di detail setiap kelas.</p></div></section>
